export const getAlertAnimation = (isAdded, indx, removedId, isMobile, activeFeedback) => {
    if (activeFeedback === "toast") {
        return null;
    }
    if (isMobile) {
        if (isAdded) {
            return "top-bottom";
        }
        if (removedId && indx < removedId) {
            return null;
        }
        return "bottom-top";
    }
    if (isAdded) {
        if (indx === 0) {
            return "right-left";
        }
        return "top-bottom";
    }
    if (removedId && indx < removedId) {
        return null;
    }
    return "bottom-top";
};
